-- Isolated test host, layered over Phase 1 fixture. Never run against production.
alter table players add column next_roll_at timestamptz,
 add column roll_lease_id uuid, add column roll_lease_expires_at timestamptz,
 add column equipment_state_roll bigint not null default 0,
 add column inventory_capacity integer not null default 2000;
update players set equipment_state_roll=equipment_genuine_rolls;
alter table player_equipment add column equipped boolean default true;
alter table inventory_gems alter column id add generated by default as identity (start with 100);
alter table inventory_gems add column genuine_roll boolean default false;
create table fixture_routes(id bigserial,player_id uuid,kind text,specimen jsonb);
create function roll_batch_unlock_status(uuid,integer) returns jsonb language sql set search_path=public,pg_catalog as $$select '{"status":"unlocked"}'::jsonb$$;
create function roll_refresh_context(uuid,timestamptz) returns jsonb language sql set search_path=public,pg_catalog as $$
 select jsonb_build_object('player',to_jsonb(p)) from players p where id=$1
$$;
-- Contract doubles for external game domains; actual deployed claim/release,
-- routing, result commit functions are loaded from the read-only audit snapshot.
create function bundle_route_roll(uuid,uuid,jsonb) returns jsonb language plpgsql set search_path=public,pg_catalog as $$begin
 if $3->>'gem_name'='bundle' then
  insert into fixture_routes(player_id,kind,specimen) values($1,'bundle',$3);
  return '{"status":"deposited","keepInInventory":false}';
 end if;
 return '{"status":"none","keepInInventory":false}';
end$$;
create schema convergence_private;
create function roll_autocraft_deposit(uuid,jsonb) returns jsonb language plpgsql set search_path=public,pg_catalog as $$begin
 if $2->>'gem_name'='error' then raise exception 'injected_deposit_error'; end if;
 insert into fixture_routes(player_id,kind,specimen) values($1,'craft',$2);
 return jsonb_build_object('deposited',true,'preserved',$2->>'gem_name'='conserved');
end$$;
create function convergence_private.autocraft_deposit(uuid,jsonb) returns jsonb language sql set search_path=public,pg_catalog as $$select roll_autocraft_deposit($1,$2)$$;
create function paradox_autocraft_deposit(uuid,jsonb) returns jsonb language sql set search_path=public,pg_catalog as $$select roll_autocraft_deposit($1,$2)$$;
create function roll_insert_inventory_specimen(uuid,jsonb) returns inventory_gems language plpgsql set search_path=public,pg_catalog as $$declare r inventory_gems;begin
 if $2->>'gem_name'='insert-error' then raise exception 'injected_insert_error'; end if;
 insert into inventory_gems(player_id,gem_name,value,final_weight,genuine_roll)
 values($1,$2->>'gem_name',($2->>'value')::numeric,1,($2->>'genuine_roll')::boolean) returning * into r;return r;
end$$;
create function sell_inventory_gem(uuid,bigint,text) returns numeric language plpgsql set search_path=public,pg_catalog as $$declare r inventory_gems;begin
 select * into strict r from inventory_gems where id=$2 and player_id=$1;
 if r.gem_name='sale-error' then raise exception 'injected_sale_error'; end if;
 update players set money=money+r.value where id=$1;
 delete from inventory_gems where id=$2;return r.value;
end$$;
create function grant_player_relic(uuid,text,integer) returns void language sql set search_path=public,pg_catalog as $$insert into fixture_routes(player_id,kind,specimen) values($1,'relic',jsonb_build_object('name',$2))$$;
